    op.alter_column('intangible_asset', 'asset_type',
           existing_type=sa.VARCHAR(), # (Tipe lama Anda mungkin berbeda, biarkan saja)
           type_=sa.Enum('...', name='intangibleassettype'), # (Tipe baru Anda)
           postgresql_using='asset_type::intangibleassettype') # <--- TAMBAHKAN BARIS INI
